#!/bin/bash

#SBATCH --job-name=importfeauredata
#SBATCH --partition=batch
#SBATCH --nodes=1
#SBATCH --ntasks=1
#SBATCH --cpus-per-task=4
#SBATCH --mem=4gb
#SBATCH --time=1:00:00
#SBATCH --export=NONE
#SBATCH --output=%x_%j.out
#SBATCH --error=%x_%j.err

# ============================================================
# Script 3. Import DADA2 outputs into QIIME 2 and filter ASVs
# ============================================================
# Created by Piotr Tymon Tuczapski
#
# PURPOSE:
# Import the ASV abundance table and representative nucleotide
# sequences generated by DADA2 into QIIME 2 for downstream
# fungal community analyses.
#
# The workflow includes:
# 1. Importing representative ASV nucleotide sequences.
# 2. Converting the ASV abundance table to BIOM format.
# 3. Importing the BIOM table into QIIME 2.
# 4. Removing ASVs represented by fewer than six reads.
# 5. Retaining samples from the four focal Lepanthes species.
#
# DATASETS:
# The commands below process the General Fungi (GF) dataset.
# The same procedure was applied separately to the Confirmed
# Mycorrhizal Fungi (CMF) dataset.
#
# REQUIRED INPUTS:
# - rep-seqs_nochim.fna:
#     Representative nucleotide sequences from DADA2.
# - seqtab_nochim.txt:
#     ASV abundance table exported from DADA2.
# - qiime2metadata.tsv:
#     Sample metadata containing the "orchid sp." column.
#
# OUTPUTS:
# - rep-seqs_nochim.qza
# - biom-table_nochim.txt
# - table_nochim.biom
# - table_nochim.qza
# - filtered_table_nochim.qza
# - orchidspfilteredtablenochim.qza
#
# NOTE:
# File paths and QIIME 2 versions reflect the original
# computing environment and should be verified before reuse.
# ============================================================


# ------------------------------------------------------------
# 1. Initialize the SLURM computing environment
# ------------------------------------------------------------

#load software
module load QIIME2/2026.04
# Configure Matplotlib for non-interactive execution.
echo "backend: Agg" > ~/.config/matplotlib/matplotlibrc
# Set locale for UTF-8 character encoding.
export LC_ALL=en_US.utf-8
export LANG=en_US.utf-8

# ------------------------------------------------------------
# 2. Import representative ASV nucleotide sequences
# ------------------------------------------------------------

# Import the DADA2-derived representative sequences
# as a QIIME 2 FeatureData[Sequence] artifact.
#
# Unique ASV identifiers must correspond to the identifiers
# used in the ASV abundance table.

qiime tools import \
  --input-path ./rep-seqs_nochim.fna \
  --type 'FeatureData[Sequence]' \
  --output-path ./rep-seqs_nochim.qza
# ------------------------------------------------------------
# 3. Prepare the DADA2 ASV abundance table
# ------------------------------------------------------------

# Add the "#OTU Table" header required for conversion
# of the tab-delimited ASV table to BIOM format.
#
# The term "OTU Table" is used here for compatibility
# with the BIOM conversion procedure. The underlying
# features are ASVs inferred using DADA2.
#
# REVIEW: Confirm that the absolute output path corresponds
# to the relative input path used in the next command.  
  echo -n "#OTU Table" | cat - ./seqtab_nochim.txt > ./biom-table_nochim.txt
# ------------------------------------------------------------
# 4. Convert the abundance table to BIOM format
# ------------------------------------------------------------

# Convert the tab-delimited ASV abundance table into
# HDF5-based BIOM format for import into QIIME 2.
biom convert -i ./biom-table_nochim.txt -o ./table_nochim.biom --table-type="OTU table" --to-hdf5
# ------------------------------------------------------------
# 6. Import the BIOM abundance table into QIIME 2
# ------------------------------------------------------------

# Import the ASV abundance table as a
# FeatureTable[Frequency] artifact.
qiime tools import \
  --input-path ./table_nochim.biom \
  --type 'FeatureTable[Frequency]' \
  --input-format BIOMV210Format \
  --output-path ./table_nochim.qza
# ------------------------------------------------------------
# 7. Remove low-abundance ASVs
# ------------------------------------------------------------

# Retain ASVs with a total frequency of at least six reads

# This filtering threshold was applied to reduce the
# influence of low-frequency sequencing artifacts
# identified during mock-community assessment.
qiime feature-table filter-features \
  --i-table ../table_nochim.qza \
  --p-min-frequency 6 \
  --o-filtered-table ../filtered_table_nochim.qza
# ------------------------------------------------------------
# 8. Retain samples from the four focal orchid species
# ------------------------------------------------------------

# Filter the ASV abundance table using sample metadata.
#
# Retain samples belonging to:
# - Lepanthes monteverdensis
# - Lepanthes falx-bellica
# - Lepanthes cribbii
# - Lepanthes mentosa
#
# This step excludes samples not assigned to these species,
# including the bark samples present in the original dataset.
#
# The metadata column "orchid sp." must contain the exact
# species names specified below.

  qiime feature-table filter-samples \
  --i-table filtered_table_nochim.qza \
  --m-metadata-file qiime2metadata.tsv \
  --p-where "[orchid sp.] IN ('Lepanthes monteverdensis', 'Lepanthes falx-bellica', 'Lepanthes cribbii', 'Lepanthes mentosa')" \
  --o-filtered-table orchidspfilteredtablenochim.qza

# ============================================================
# End of Script 3
# ============================================================
